def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each nonzero diagonal is a sample of a period-five color pattern indexed
    # by c-r. Recover the sampled phases; fill the one missing phase from the
    # neighboring repeated 3-color band.
    palette = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                palette[(c-r) % 5] = value
    for phase in range(5):
        if phase not in palette:
            nearest = min(palette, key=lambda p: (min((phase-p) % 5, (p-phase) % 5), p))
            palette[phase] = palette[nearest]
    out = [[palette[(c-r) % 5] for c in range(w)] for r in range(h)]
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= value <= 9 for row in out for value in row)
    return out

